parameters.jsCode:
// The chase run. One decision per customer, and most of those decisions are
// about not sending anything.
//
// Every rule below is either a suppression - do not chase, and say why - or
// an escalation - chase harder, or hand it to a person. Nothing is sent from
// here: this node decides, and the Switch after it routes. A customer with
// nothing to do still comes out, carrying the reason, so the execution shows
// who was left alone and why.

const cfg = $('Set Collection Policy').first().json;

// Google Sheets returns a blank item for an empty tab; drop those.
const clean = (bag) => (bag || []).filter((r) => r && Object.keys(r).length);
const customers = clean($('Aggregate Customer Data').first().json.rows);
const invoices = clean($('Aggregate Invoice Data').first().json.rows);
const payments = clean($('Aggregate Payment Data').first().json.rows);
const chases = clean($('Aggregate Chase History').first().json.rows);

const DAY = 86400000;
const SETTLED = ['paid', 'void', 'cancelled', 'written off', 'write-off', 'credited'];

const num = (v) => {
  const n = Number(String(v == null ? '' : v).replace(/[^0-9.-]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const round2 = (v) => Math.round((Number(v) || 0) * 100) / 100;

// "ACME Ltd." and "Acme Limited" are one customer. Same normalisation as the
// payables template: off with the legal form, the accents and the punctuation.
const LEGAL = /\b(ltd|limited|llc|inc|incorporated|corp|corporation|co|company|gmbh|ag|bv|nv|sa|sas|sarl|srl|spa|oy|ab|as|aps|plc|pty|kg|ug|sl|kft|doo)\b/g;
const key = (name) => String(name || '').toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/&/g, ' and ').replace(/[^a-z0-9 ]/g, ' ')
  .replace(LEGAL, ' ').replace(/\s+/g, ' ').trim();

// A date column in a sheet arrives in whatever shape the sheet feels like:
// 2026-03-04, 04/03/2026, or 46085 - which is Sheets' own serial, days since
// 30 December 1899, and reaches a Code node as a plain number. All three end
// up at local midnight, because a due date is a calendar day and not an
// instant: read as UTC and compared with a local today, it is the off-by-one
// that chases somebody a day early.
function calendarDay(value) {
  const s = String(value == null ? '' : value).trim();
  if (!s) return null;
  if (/^\d{5}(\.\d+)?$/.test(s)) {
    const d = new Date(Date.UTC(1899, 11, 30) + Math.round(Number(s)) * DAY);
    return new Date(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()).getTime();
  }
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])).getTime();
  m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/);
  if (m) {
    const a = Number(m[1]);
    const b = Number(m[2]);
    const dayFirst = a > 12 ? true : b > 12 ? false : String(cfg.date_order) !== 'MDY';
    return new Date(Number(m[3]), (dayFirst ? b : a) - 1, dayFirst ? a : b).getTime();
  }
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
}

const today = new Date();
today.setHours(0, 0, 0, 0);

const daysSince = (value) => {
  const t = calendarDay(value);
  return t === null ? null : Math.round((today.getTime() - t) / DAY);
};

// How long since we last wrote to them, counted the way an office counts:
// a chaser sent on Friday is one day old on Monday, not three.
function workdaysSince(value) {
  const t = calendarDay(value);
  if (t === null) return null;
  if (t >= today.getTime()) return 0;
  let count = 0;
  const d = new Date(t);
  for (let guard = 0; guard < 2000 && d.getTime() < today.getTime(); guard++) {
    d.setDate(d.getDate() + 1);
    const w = d.getDay();
    if (w !== 0 && w !== 6) count++;
  }
  return count;
}

const median = (list) => {
  const s = [...list].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
};

// --- what we know about each customer, before looking at the invoices ------

const profiles = new Map();
for (const c of customers) {
  const k = key(c.customer_name || c.name);
  if (k) profiles.set(k, c);
}

// Money of theirs that is in our bank and matched to nothing. Chasing
// somebody for an amount we are already holding is the fastest way to lose an
// account that was never late in the first place.
const unmatched = new Map();
for (const p of payments) {
  const state = String(p.status || '').toLowerCase();
  if (state === 'allocated' || state === 'ignored') continue;
  const k = key(p.customer_name);
  const left = round2(num(p.amount) - num(p.allocated_amount));
  if (!k || left <= 0.01) continue;
  unmatched.set(k, round2((unmatched.get(k) || 0) + left));
}

// The log is history: one row per thing we sent. What matters out of it is
// the last row's level, how long ago it went, and how many times in all.
const lastChase = new Map();
const lastEscalation = new Map();
const chaseCount = new Map();
for (const r of chases) {
  const k = key(r.customer_name);
  const when = calendarDay(r.sent_on);
  if (!k || when === null) continue;
  const action = String(r.action || '').toLowerCase();
  if (action.startsWith('chase')) chaseCount.set(k, (chaseCount.get(k) || 0) + 1);
  // Anche una consegna al recupero crediti e' un contatto: se non contasse,
  // un rifiuto del responsabile amministrativo gli farebbe ripetere la stessa
  // domanda la mattina dopo, e quella dopo ancora.
  if (action.startsWith('chase') || action.startsWith('handover')) {
    const prev = lastChase.get(k);
    if (!prev || when >= prev.when) {
      lastChase.set(k, { when, sent_on: r.sent_on, level: Number(r.level) || 0 });
    }
  }
  if (action.startsWith('escalate') || action.startsWith('handover')) {
    const prev = lastEscalation.get(k);
    if (!prev || when >= prev.when) lastEscalation.set(k, { when, sent_on: r.sent_on });
  }
}

// --- the settings, each with a default, so a blank cell cannot stop the run -

const graceDays = Number(cfg.grace_days) || 3;
const habitCap = Number(cfg.habit_grace_cap) || 7;
const level2 = Number(cfg.level_2_days) || 14;
const level3 = Number(cfg.level_3_days) || 30;
const handoverDays = Number(cfg.handover_days) || 60;
const gapDays = Number(cfg.days_between_chases) || 5;
const escalationGap = Number(cfg.days_between_escalations) || 14;
const floor = Number(cfg.chase_floor) || 0;
const promiseGrace = Number(cfg.promise_grace_days) || 1;

const LADDER = {
  1: {
    subject: (n, m) => `Reminder: ${n} invoice(s) past due, ${m}`,
    opening: 'A reminder that the invoice(s) below are past their due date. If they are '
      + 'already scheduled for payment, or if something is wrong with one of them, '
      + 'replying to this email is enough - the replies are read.',
  },
  2: {
    subject: (n, m) => `Overdue: ${n} invoice(s), ${m}`,
    opening: 'These invoices are now well past due, and we have written once already. '
      + 'Please either pay them or tell us what is holding them up: a date we can rely '
      + 'on is worth more to us than silence.',
  },
  3: {
    subject: (n, m) => `Final notice: ${n} invoice(s), ${m}`,
    opening: 'This is the last automatic notice on these invoices. Unless they are paid, '
      + 'or we agree a date, the account goes on hold and the balance is passed on for '
      + 'collection. We would much rather hear from you than do that.',
  },
};

// --- one pass per customer -------------------------------------------------

const byCustomer = new Map();
for (const r of invoices) {
  const k = key(r.customer_name);
  if (!k) continue;
  if (!byCustomer.has(k)) byCustomer.set(k, []);
  byCustomer.get(k).push(r);
}

const out = [];

for (const [k, rows] of byCustomer) {
  const profile = profiles.get(k) || {};
  const name = profile.customer_name || profile.name || rows[0].customer_name;
  const currency = String(profile.currency || rows[0].currency || cfg.default_currency || '')
    .toUpperCase();
  const money = (v) => `${currency} ${round2(v).toFixed(2)}`.trim();

  // How late this customer pays when they do pay. The median, not the mean:
  // one invoice that sat in a drawer for a year should not rewrite the habit
  // of a customer who is otherwise five days late every single time.
  const lateness = [];
  for (const r of rows) {
    const paid = calendarDay(r.paid_on);
    const owedDate = calendarDay(r.due_date);
    if (paid !== null && owedDate !== null) lateness.push(Math.round((paid - owedDate) / DAY));
  }
  const habit = lateness.length >= 3
    ? Math.min(Math.max(Math.round(median(lateness)), 0), habitCap)
    : 0;

  const open = rows.filter((r) =>
    !SETTLED.includes(String(r.status || '').toLowerCase()) &&
    round2(num(r.total_amount) - num(r.amount_paid)) > 0.01);
  if (!open.length) continue;

  const seen = lastChase.get(k);
  const sinceChase = seen ? workdaysSince(seen.sent_on) : null;
  const escalated = lastEscalation.get(k);
  const sinceEscalation = escalated ? daysSince(escalated.sent_on) : null;

  // La cortesia si concede una volta sola: il credito d'abitudine ritarda il
  // primo contatto, non il secondo.
  const grace = graceDays + (seen ? 0 : habit);

  const due = [];
  const disputed = [];
  const promised = [];
  const waiting = [];
  let broken = null;
  let exposure = 0;

  for (const r of open) {
    const owedOnIt = round2(num(r.total_amount) - num(r.amount_paid));
    const over = daysSince(r.due_date);
    const item = {
      number: String(r.invoice_number || '').trim(),
      issued: String(r.invoice_date || '').trim(),
      due: String(r.due_date || '').trim(),
      over,
      owed: owedOnIt,
      part: num(r.amount_paid) > 0.01,
    };
    exposure = round2(exposure + owedOnIt);

    if (String(r.status || '').toLowerCase() === 'disputed') {
      disputed.push({ ...item, why: String(r.dispute_reason || '').trim() || 'no reason recorded' });
      continue;
    }

    const promiseAge = r.promised_on ? daysSince(r.promised_on) : null;
    if (promiseAge !== null) {
      if (promiseAge <= promiseGrace) {
        promised.push({ ...item, on: String(r.promised_on).trim() });
        continue;
      }
      // Una promessa scaduta non e' un ritardo qualunque: e' la seconda volta
      // che questa fattura non viene pagata, e la scala sale di un gradino.
      if (!broken || promiseAge > broken.age) {
        broken = { ...item, on: String(r.promised_on).trim(), age: promiseAge };
      }
    }

    if (over === null || over <= grace) {
      waiting.push(item);
      continue;
    }
    due.push(item);
  }

  due.sort((a, b) => (b.over || 0) - (a.over || 0));

  const owed = round2(due.reduce((s, i) => s + i.owed, 0));
  const worst = due.reduce((m, i) => Math.max(m, i.over || 0), 0);
  const cash = unmatched.get(k) || 0;
  const limit = num(profile.credit_limit);
  const fallbackEmail = (rows.find((r) => r.customer_email) || {}).customer_email;
  const email = String(profile.email || fallbackEmail || '').trim();
  const owner = String(profile.account_manager_email || cfg.ar_clerk_email || '').trim();

  // Il gradino che meriterebbero, e il gradino che gli tocca. Il secondo non
  // supera mai di uno l'ultimo usato: il primo contatto e' un promemoria
  // anche su una fattura di quaranta giorni, perche' il motivo per cui non e'
  // stata pagata potrebbe essere che non e' mai arrivata.
  const deserved = !due.length ? 0
    : worst >= handoverDays ? 4
    : worst >= level3 ? 3
    : worst >= level2 ? 2 : 1;
  const wanted = deserved && broken ? Math.min(4, deserved + 1) : deserved;
  const level = wanted ? Math.max(1, Math.min(wanted, (seen ? seen.level : 0) + 1)) : 0;
  const rung = LADDER[Math.min(3, Math.max(1, level))];

  // Una contestazione e uno sconfinamento sono la stessa decisione: il
  // cliente non si sollecita, e se ne occupa chi ha il rapporto. Con un
  // limite, pero'. Ricordarglielo ogni mattina finche' non ha risolto non e'
  // sollecitare il cliente, e' sollecitare il collega.
  const overLimit = limit > 0 && exposure > limit;
  const held = disputed.length > 0 || overLimit;
  const escalationDue = sinceEscalation === null || sinceEscalation >= escalationGap;

  let action = 'none';
  let reason = '';

  if (held && escalationDue) {
    action = 'escalate';
    reason = [
      disputed.length
        ? `${disputed.length} invoice(s) in dispute: ${disputed.map((d) => d.number).join(', ')}`
        : '',
      overLimit ? `${money(exposure)} outstanding against a credit limit of ${money(limit)}` : '',
    ].filter(Boolean).join('; ');
  } else if (held) {
    action = 'none';
    reason = `${disputed.length ? 'in dispute' : 'over the credit limit'}, and with `
      + `${owner || 'the account manager'} since ${escalated.sent_on}: the customer is not `
      + 'chased while it is';
  } else if (!due.length) {
    action = 'none';
    reason = promised.length ? `${promised.length} invoice(s) promised for a date still to come`
      : disputed.length ? 'everything open is in dispute, and that has been escalated already'
      : `nothing overdue by more than the ${grace} day grace`;
  } else if (cash >= owed - 0.01) {
    action = 'none';
    reason = `${money(cash)} of theirs is in our account, matched to nothing, against `
      + `${money(owed)} overdue. Match the payment before writing to them`;
  } else if (owed < floor) {
    action = 'none';
    reason = `${money(owed)} overdue, under the ${money(floor)} floor`;
  } else if (sinceChase !== null && sinceChase < gapDays) {
    action = 'none';
    reason = `last written to ${sinceChase} working day(s) ago at level ${seen.level}, `
      + `and the gap is ${gapDays}`;
  } else if (!email) {
    action = escalationDue ? 'escalate' : 'none';
    reason = escalationDue
      ? `${money(owed)} overdue and no email address on file for them`
      : `${money(owed)} overdue, still no email address, and that was raised on ${escalated.sent_on}`;
  } else if (level >= 4) {
    action = 'handover';
    reason = `${money(owed)} overdue, the oldest by ${worst} days, after ${chaseCount.get(k) || 0} chase(s)`;
  } else {
    action = 'chase';
    reason = `level ${level}, oldest overdue by ${worst} days`;
  }

  // --- what the customer reads ---------------------------------------------

  const pad = (s, n) => String(s == null ? '' : s).padEnd(n);
  const rpad = (s, n) => String(s == null ? '' : s).padStart(n);
  const table = (list) => [
    `${pad('Invoice', 18)}${pad('Issued', 12)}${pad('Due', 12)}${rpad('Days', 6)}${rpad('Amount', 15)}`,
    ...list.map((i) => `${pad(i.number, 18)}${pad(i.issued, 12)}${pad(i.due, 12)}`
      + `${rpad(i.over === null ? '?' : i.over, 6)}${rpad(money(i.owed), 15)}`),
  ].join('\n');

  const bucket = (from, to) => round2(due
    .filter((i) => (i.over || 0) >= from && (i.over || 0) <= to)
    .reduce((s, i) => s + i.owed, 0));

  const statement = [
    rung.opening,
    '',
    table(due),
    '',
    `${pad('Total overdue', 48)}${rpad(money(owed), 15)}`,
    `  1-30 days: ${money(bucket(1, 30))}   31-60: ${money(bucket(31, 60))}   `
      + `over 60: ${money(bucket(61, 99999))}`,
    waiting.length ? `\nNot yet due, and not being asked for: ${waiting.length} invoice(s), `
      + `${money(waiting.reduce((s, i) => s + i.owed, 0))}.` : '',
    promised.length ? `\nLeft out because you have given us a date:\n${table(promised)}` : '',
    disputed.length ? '\nLeft out because they are in dispute - we are not asking for these:\n'
      + disputed.map((d) => `  ${d.number}  ${money(d.owed)}  (${d.why})`).join('\n') : '',
    broken ? `\nInvoice ${broken.number} was promised for ${broken.on}, ${broken.age} day(s) ago.` : '',
  ].filter((l) => l !== '').join('\n');

  // --- what a colleague reads ----------------------------------------------

  const habitLine = lateness.length >= 3
    ? `${habit === 0 ? 'on time, as a rule' : `about ${median(lateness)} day(s) late, as a rule`}`
      + ` (${lateness.length} paid invoices)`
    : 'not enough history to say';

  const internal = [
    `${pad('Customer', 20)}${name}`,
    `${pad('Owes', 20)}${money(exposure)} in all, ${money(owed)} of it overdue`,
    `${pad('Credit limit', 20)}${limit ? money(limit) : 'none on file'}`,
    `${pad('Oldest overdue', 20)}${worst ? `${worst} days` : 'nothing overdue'}`,
    `${pad('Open invoices', 20)}${open.length} (${disputed.length} disputed, ${promised.length} promised)`,
    `${pad('Pays', 20)}${habitLine}`,
    `${pad('Unmatched cash', 20)}${cash ? money(cash) : 'none'}`,
    `${pad('Chased', 20)}${seen
      ? `${chaseCount.get(k) || 0} time(s), last on ${seen.sent_on} at level ${seen.level}`
      : 'never'}`,
    `${pad('Escalated', 20)}${escalated ? escalated.sent_on : 'never'}`,
    '',
    `Why this is in front of you: ${reason}`,
    disputed.length ? `\nIn dispute:\n`
      + disputed.map((d) => `  ${d.number}  ${money(d.owed)}  ${d.why}`).join('\n') : '',
    due.length ? `\nOverdue:\n${table(due)}` : '',
  ].filter((l) => l !== '').join('\n');

  out.push({
    json: {
      customer_name: name,
      customer_key: k,
      customer_email: email,
      account_manager_email: owner,
      action,
      level,
      reason,
      currency,
      subject_line: due.length ? rung.subject(due.length, money(owed)) : `Account review: ${name}`,
      statement,
      internal,
      invoices_chased: due.map((i) => i.number).join(', '),
      amount_due: owed,
      exposure,
      credit_limit: limit,
      oldest_days: worst,
      habit_days: habit,
      open_count: open.length,
      disputed_count: disputed.length,
      promised_count: promised.length,
      unmatched_cash: cash,
      chase_count: chaseCount.get(k) || 0,
      last_chased: seen ? seen.sent_on : '',
      broken_promise: broken ? `${broken.number}, promised for ${broken.on}` : '',
    },
  });
}

// Il piu' vecchio per primo: se qualcosa si rompe a meta' giro, si e' rotto
// dopo i clienti che pesavano di piu'.
out.sort((a, b) => b.json.oldest_days - a.json.oldest_days);
return out;

parameters.message:
=This account was taken out of today's automatic chase run.

{{ $json.internal }}

Nothing has been sent to the customer, and nothing will be while this stands. Settle it in the sheet - clear the dispute, raise the limit, put an address on the row - and the next run picks the account up where the ladder left it. Until then you get this once a fortnight, not every morning.

=This account has been through the whole ladder and is still unpaid.

{{ $json.internal }}

Agreeing hands the balance to collections and the relationship with it. Refusing keeps it in-house, and the account is left alone until somebody moves it: the ladder has nothing above this.

