// Bank credits in, open invoices out. This node decides which invoice a
// payment belongs to, and it is the reason the chase run can be trusted: an
// unmatched payment is a customer about to be chased for money they have
// already sent.
//
// Four ways to read a payment, tried in the order of how much they prove:
//
//   1. the reference quotes invoice numbers, and those numbers add up;
//   2. exactly one open invoice of theirs is for exactly this amount;
//   3. exactly one combination of their open invoices adds up to it - the
//      customer who settles five invoices with one transfer and references
//      none of them is the ordinary case, not the exotic one;
//   4. nothing adds up, so oldest first, and the last invoice is left part
//      paid.
//
// Two combinations that both add up is not a tie to be broken by ordering:
// it is a question, and it goes to a person with both answers written out.
// The same for a payer we cannot name. Everything here either allocates with
// a stated reason or says what it could not work out.

const cfg = $('Set Matching Rules').first().json;

const clean = (bag) => (bag || []).filter((r) => r && Object.keys(r).length);
const payments = clean($('Aggregate Bank Payments').first().json.rows);
const invoices = clean($('Aggregate Open Invoices').first().json.rows);

const SETTLED = ['paid', 'void', 'cancelled', 'written off', 'write-off', 'credited'];

const num = (v) => {
  const n = Number(String(v == null ? '' : v).replace(/[^0-9.-]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const round2 = (v) => Math.round((Number(v) || 0) * 100) / 100;
const LEGAL = /\b(ltd|limited|llc|inc|incorporated|corp|corporation|co|company|gmbh|ag|bv|nv|sa|sas|sarl|srl|spa|oy|ab|as|aps|plc|pty|kg|ug|sl|kft|doo)\b/g;
const key = (name) => String(name || '').toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/&/g, ' and ').replace(/[^a-z0-9 ]/g, ' ')
  .replace(LEGAL, ' ').replace(/\s+/g, ' ').trim();
const flat = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');

const feeAbs = Number(cfg.fee_tolerance_abs) || 25;
const feePct = Number(cfg.fee_tolerance_pct) || 5;
const maxSize = Number(cfg.max_combination_size) || 4;
const maxCandidates = Number(cfg.max_candidates) || 14;
const oldestFirst = String(cfg.allocate_oldest_first) !== 'false';

// A transfer that lands 18 EUR short on 4,000 is not a short payment, it is
// the correspondent bank's fee. A transfer 18 short on 30 is a different
// invoice. So the tolerance is a flat amount capped at a share of what is
// being settled: never the percentage alone, and never the flat sum alone.
const tolerance = (value) =>
  Math.max(0.01, Math.min(feeAbs, Math.abs(value) * feePct / 100));

const open = invoices
  .filter((r) => !SETTLED.includes(String(r.status || '').toLowerCase()) &&
    round2(num(r.total_amount) - num(r.amount_paid)) > 0.01)
  .map((r) => ({
    number: String(r.invoice_number || '').trim(),
    flat: flat(r.invoice_number),
    digits: String(r.invoice_number || '').replace(/\D/g, ''),
    customer: String(r.customer_name || '').trim(),
    ckey: key(r.customer_name),
    currency: String(r.currency || cfg.default_currency || '').toUpperCase(),
    due: String(r.due_date || '').trim(),
    total: round2(num(r.total_amount)),
    paid: round2(num(r.amount_paid)),
    owed: round2(num(r.total_amount) - num(r.amount_paid)),
  }))
  .sort((a, b) => String(a.due).localeCompare(String(b.due)));

// Which invoice numbers a reference quotes. Two readings, because bank
// references get mangled in two different ways: the whole number with its
// punctuation eaten ("INV-2026/0042" as "inv20260042"), and the digits on
// their own ("payment 0042"). The digits need a boundary, or invoice 42 hides
// inside every reference with a 42 anywhere in it.
function quoted(text) {
  const hay = String(text || '').toLowerCase();
  const squashed = hay.replace(/[^a-z0-9]/g, '');
  const hits = [];
  for (const inv of open) {
    if (inv.owed <= 0.01) continue;
    if (inv.flat.length >= 5 && squashed.includes(inv.flat)) { hits.push(inv); continue; }
    if (inv.digits.length >= 4 &&
        new RegExp(`(^|[^0-9])${inv.digits}([^0-9]|$)`).test(hay)) hits.push(inv);
  }
  return hits;
}

// Who sent it, when the reference does not say. Every word of the customer's
// name has to be in the text, and if two customers answer to it then nobody
// does: a guess here pays one company's debt with another company's money.
function payer(text) {
  const hay = key(text);
  if (!hay) return null;
  const hits = new Set();
  for (const inv of open) {
    if (!inv.ckey) continue;
    const words = inv.ckey.split(' ').filter((w) => w.length >= 4);
    if (words.length ? words.every((w) => hay.includes(w)) : hay.includes(inv.ckey)) {
      hits.add(inv.ckey);
    }
  }
  return hits.size === 1 ? [...hits][0] : null;
}

// Every combination of at most `maxSize` invoices that comes to the amount,
// and it stops at three: past three there is nothing left to count, the
// answer is already "ask somebody". The pool is the oldest candidates, and
// the walk abandons a branch as soon as it has overshot - which is safe
// because an open balance is never negative.
function combinations(pool, target) {
  const room = tolerance(target);
  const found = [];
  const chosen = [];
  const walk = (start, sum) => {
    if (found.length >= 3) return;
    if (chosen.length && Math.abs(sum - target) <= room) {
      found.push(chosen.slice());
      return;
    }
    if (chosen.length >= maxSize || sum - target > room) return;
    for (let i = start; i < pool.length; i++) {
      chosen.push(pool[i]);
      walk(i + 1, round2(sum + pool[i].owed));
      chosen.pop();
    }
  };
  walk(0, 0);
  return found;
}

const allocations = [];
const settlements = [];
const exceptions = [];

const names = (list) => list.map((i) => i.number).join(' + ');

// One allocation line, and the running balance of that invoice moves with it.
// Two payments in the same run against the same invoice have to see each
// other, or the second one writes the first one out of the sheet.
function post(inv, take, payment, how, clear) {
  const paidAfter = clear ? inv.total : round2(inv.paid + take);
  const written = clear ? round2(inv.total - inv.paid - take) : 0;
  const left = clear ? 0 : round2(inv.total - paidAfter);
  inv.paid = paidAfter;
  inv.owed = left;
  allocations.push({
    kind: 'allocation',
    invoice_number: inv.number,
    customer_name: inv.customer,
    currency: inv.currency,
    allocated: round2(take),
    amount_paid_after: paidAfter,
    outstanding_after: left,
    status_after: left <= 0.01 ? 'paid' : 'part paid',
    paid_on: String(payment.payment_date || '').trim(),
    payment_reference: String(payment.reference || '').trim(),
    matched_by: how,
    written_off: written > 0.01 ? written : 0,
    note: written > 0.01
      ? `${inv.currency} ${written.toFixed(2)} short, within the fee tolerance and written off`
      : '',
  });
  return round2(take);
}

// Oldest first until the money runs out. Standard practice, and written on
// the row as the reason rather than left to be inferred from the balances.
function spread(list, amount, payment, how) {
  let left = round2(amount);
  const touched = [];
  for (const inv of list) {
    if (left <= 0.01) break;
    if (inv.owed <= 0.01) continue;
    const take = Math.min(left, inv.owed);
    const clears = inv.owed - take <= tolerance(inv.owed);
    post(inv, take, payment, how, clears);
    touched.push(inv);
    left = round2(left - take);
  }
  return { left, touched };
}

for (const p of payments) {
  const state = String(p.status || '').toLowerCase();
  if (state === 'allocated' || state === 'ignored') continue;

  const amount = round2(num(p.amount));
  // Un addebito non e' un incasso: le righe in uscita stanno sullo stesso
  // estratto conto e non c'entrano niente con le fatture che abbiamo emesso.
  if (amount <= 0) continue;

  const reference = String(p.reference || '').trim();
  const currency = String(p.currency || cfg.default_currency || '').toUpperCase();
  const when = String(p.payment_date || '').trim();
  const bankRef = String(p.bank_ref || '').trim() || `${when}|${reference}|${amount}`;
  const text = `${reference} ${p.description || ''} ${p.payer_name || ''} ${p.customer_name || ''}`;
  const cash = (v) => `${currency} ${round2(v).toFixed(2)}`.trim();
  const head = `  ${cash(amount)}  ${when || 'no date'}  "${reference || 'no reference'}"`;

  const raise = (why, detail) => {
    exceptions.push({
      kind: 'exception', bank_ref: bankRef, payment_reference: reference, payment_date: when,
      amount, currency, payer: String(p.payer_name || p.customer_name || '').trim(),
      why, detail: detail || '',
      line: `${head}\n      ${why}${detail ? `\n      ${detail}` : ''}`,
    });
  };

  const settle = (status, allocated, to, how) => {
    settlements.push({
      kind: 'payment', bank_ref: bankRef, payment_reference: reference, payment_date: when,
      customer_name: to.length ? to[0].customer : String(p.payer_name || p.customer_name || '').trim(),
      status, allocated_amount: round2(allocated), allocated_to: names(to),
      matched_by: how, amount, currency,
    });
  };

  const quotedHits = quoted(text);
  const who = quotedHits.length ? null : payer(text);
  const mine = who ? open.filter((i) => i.ckey === who && i.owed > 0.01) : [];

  if (!quotedHits.length && !who) {
    raise('no invoice number in the reference, and the payer matches no single customer',
      'Allocate it by hand, or add the name they pay under to the Customers tab');
    settle('unallocated', 0, [], 'nothing to go on');
    continue;
  }
  if (!quotedHits.length && !mine.length) {
    raise(`nothing is open for ${who}`,
      'Either it is a payment on account, or the invoice is not in the sheet yet');
    settle('unallocated', 0, [], 'no open invoice');
    continue;
  }

  let matched = null;
  let how = '';

  if (quotedHits.length) {
    matched = quotedHits;
    how = `the invoice number(s) in the reference: ${names(quotedHits)}`;
  } else {
    const exact = mine.filter((i) => Math.abs(i.owed - amount) <= tolerance(i.owed));
    if (exact.length === 1) {
      matched = exact;
      how = `the only open invoice of theirs for ${cash(amount)}`;
    } else {
      const sets = combinations(mine.slice(0, maxCandidates), amount);
      if (sets.length === 1) {
        matched = sets[0];
        how = `the one combination of their invoices that adds up: ${names(sets[0])}`;
      } else if (sets.length > 1) {
        raise(`${sets.length >= 3 ? 'three or more' : 'two'} sets of their invoices come to `
          + 'this amount, and picking one of them would be a guess',
          sets.map((s) => names(s)).join('   or   '));
        settle('unallocated', 0, [], 'more than one reading');
        continue;
      }
    }
  }

  if (!matched) {
    if (!oldestFirst) {
      raise('no invoice, and no combination of invoices, comes to this amount',
        `${mine.length} open, ${cash(mine.reduce((s, i) => s + i.owed, 0))} in all`);
      settle('unallocated', 0, [], 'nothing adds up');
      continue;
    }
    const run = spread(mine, amount, p, 'oldest first: nothing added up exactly');
    settle(run.left > 0.01 ? 'part allocated' : 'allocated',
      amount - run.left, run.touched, 'oldest first');
    const short = run.touched.filter((i) => i.owed > 0.01);
    if (run.left > 0.01) {
      raise(`${cash(run.left)} left over once everything open was paid`,
        'That is a credit on their account: leave it there, or refund it');
    } else if (short.length) {
      raise('part payment', `spread oldest first over ${names(run.touched)}; `
        + `${short[0].number} is still ${cash(short[0].owed)} short`);
    }
    continue;
  }

  const wanted = round2(matched.reduce((s, i) => s + i.owed, 0));

  if (Math.abs(amount - wanted) <= tolerance(wanted)) {
    // Dentro la tolleranza: le fatture si chiudono tutte, e la differenza -
    // che sono le spese bancarie - resta scritta sull'ultima.
    const short = round2(Math.max(0, wanted - amount));
    matched.forEach((inv, index) => {
      const last = index === matched.length - 1;
      post(inv, last ? round2(inv.owed - short) : inv.owed, p, how, true);
    });
    settle('allocated', wanted - short, matched, how);
  } else if (amount < wanted) {
    const run = spread(matched, amount, p, `${how}, short paid, oldest first`);
    settle('allocated', amount - run.left, matched, how);
    raise('short payment', `${cash(wanted - amount)} short of ${names(matched)}, which comes to `
      + `${cash(wanted)}. Allocated oldest first, and the balance stays open`);
  } else {
    spread(matched, wanted, p, how);
    settle('part allocated', wanted, matched, how);
    raise('overpayment', `${cash(amount - wanted)} more than ${names(matched)} needed. `
      + 'Left as a credit on their account');
  }
}

// Le eccezioni per ultime, cosi' in fondo all'esecuzione c'e' esattamente la
// lista di cio' che nessuno ha ancora guardato.
return [...allocations, ...settlements, ...exceptions].map((json) => ({ json }));

